handlers.set.help:
if (el.dataset.set === 'help'){
      S.showHelp = !S.showHelp;
      save();
      applyHelp(true);          // ★ v5.2：撑开/收回，而不是整页瞬移（见 applyHelp 的注释）
      el.setAttribute('aria-checked', S.showHelp ? 'true' : 'false');
    }

handlers.set.ideaReview:
else if (el.dataset.set === 'ideaReview'){
      S.ideaReview = !S.ideaReview; save();
      el.setAttribute('aria-checked', S.ideaReview ? 'true' : 'false');
      ideaUI.reviewOpen = null;                     // 重开后回到"按频率自动"
      applyHelp(); refresh();
      toast(S.ideaReview ? '想法回顾已打开' : '想法回顾已关闭');
    }

handlers.set.lite:
else if (el.dataset.set === 'lite'){
      const on = !document.documentElement.classList.contains('soft-render');
      try { localStorage.setItem(LITE_KEY, on ? 'on' : 'off'); } catch (e){}
      applyLite(on);
      el.setAttribute('aria-checked', on ? 'true' : 'false');
      toast(on ? '已开启流畅模式（更省性能）' : '已切回完整视觉');
    }

handlers.set.voice:
else if (el.dataset.set === 'voice'){
      S.voice = !S.voice; save();
      el.setAttribute('aria-checked', S.voice ? 'true' : 'false');
      if (S.voice && !voiceReady()) toast('当前设备不支持离线语音，长按仍走键盘输入');
      else toast(S.voice ? '已开启语音输入（长按圆钮说话）' : '已关闭语音输入');
    }

handlers.set.autoDoneParent:
else if (el.dataset.set === 'autoDoneParent'){
      S.autoDoneParent = !S.autoDoneParent; save();
      el.setAttribute('aria-checked', S.autoDoneParent ? 'true' : 'false');
      toast(S.autoDoneParent ? '开着：子任务做完，父任务会跟着打勾' : '关着：子任务归子任务，父任务要自己勾');
