handlers.set.notify:
else if (el.dataset.set === 'notify'){
      S.notify = !S.notify; save();
      el.setAttribute('aria-checked', S.notify ? 'true' : 'false');
      refreshNotifyPerm();
      refreshNotifyExact();
      const n = notifyReconcile();
      if (!notifyBridge()) toast('这个壳没有通知桥：网页版 / iPhone 上不弹系统通知');
      else if (S.notify) toast(n ? ('已打开提醒 · 排了 ' + n + ' 条') : '已打开提醒 · 现在还没有写了日期的条目');
      else toast('已关闭提醒，排出去的都取消了');
    }

handlers.set.alarmfull:
else if (el.dataset.set === 'alarmfull'){
      const nx = !notifyAlarmFull();
      if (setNotifyAlarmFull(nx)){
        el.setAttribute('aria-checked', nx ? 'true' : 'false');
        refreshNotifyExact();
        toast(nx ? '开着：锁屏时会弹出响铃页' : '关着：只发一条通知，声音跟随手机的静音 / 震动 / 响铃');
      } else toast('这个壳没有通知桥');
    }

handlers.data.theme:
if (el.dataset.theme !== undefined){
    applyTheme(el.dataset.theme, true);
    const seg = el.closest('.seg');
    if (seg) seg.querySelectorAll('.segbtn').forEach(b => {
      const on = b.dataset.theme === S.theme;
      b.classList.toggle('on', on);
      b.setAttribute('aria-pressed', on ? 'true' : 'false');
    });
    syncSegPills(true);              // 主题这一档也走同一套换挡动画
    return;
  }

handlers.data.aipriv:
if (el.dataset.aipriv !== undefined){
    const v = el.dataset.aipriv;
    S.aiMode = (v === 'title' || v === 'full') ? v : 'off';
    save(); refresh();
    toast(S.aiMode === 'off' ? 'AI 已关闭：以后一个字都不出这台手机'
      : (S.aiMode === 'title' ? 'AI 已打开：只把标题发出去' : 'AI 已打开：标题、原文和时间轴都会发出去'));
    return;
  }

handlers.data.datepart:
if (el.dataset.datepart !== undefined){
    const p = el.dataset.datepart;
    if (p === 'y' || p === 'm' || p === 'd'){
      S.dateShow[p] = !S.dateShow[p];
      save();
      el.classList.toggle('on', S.dateShow[p]);
      el.setAttribute('aria-pressed', S.dateShow[p] ? 'true' : 'false');
      const pv = document.getElementById('datePrev');
      if (pv) pv.textContent = dateText('2026-10-04') || '（不显示）';
    }
    return;
  }

handlers.data.haptic:
if (el.dataset.haptic !== undefined){
    const v = el.dataset.haptic;
    S.haptic = ['off', 'low', 'std', 'high'].includes(v) ? v : 'std';
    save();
    const seg = el.closest('.seg');
    if (seg) seg.querySelectorAll('.segbtn').forEach(b => {
      const on = b.dataset.haptic === S.haptic;
      b.classList.toggle('on', on);
      b.setAttribute('aria-pressed', on ? 'true' : 'false');
    });
    syncSegPills(true);
    buzz(45);                    // 试震：选「关」时 buzz 自己会返回，不会有动静
    return;
  }

handlers.data.capzone:
if (el.dataset.capzone){
    const cz = el.dataset.capzone;
    S.captureZone = (cz === 'idea' || cz === 'auto') ? cz : (validZoneKey(cz) ? cz : 'auto');
    save(); refresh();
    toast(S.captureZone === 'idea' ? '以后没写时间的条目直接长成想法'
      : S.captureZone === 'auto' ? '以后没写时间的条目交给 AI 判：念头进想法，正经事进长期'
      : '以后没写时间的条目默认进「' + zoneNameOf(S.captureZone) + '」');
    return;
  }

handlers.act.setfold:
if (act === 'setfold'){
    const key = el.dataset.key || '';
    const i = S.setOpen.indexOf(key);
    if (i >= 0) S.setOpen.splice(i, 1); else S.setOpen.push(key);
    save();
    const nowOpen = S.setOpen.indexOf(key) >= 0;
    const card = el.closest('.set-card');
    const body = card && card.querySelector('.set-body');
    /* 量内容高：把 max-height 临时放开量一次（同 setToolsOpen 的手法）。收起态被压成 0 高，
       直接量只能得到 0；而展开方向要的就是"展开后该有多高"。全程在同一个任务里，不会绘制。 */
    let h = 0, mt = '0px';
    if (body){
      const was = body.style.maxHeight;
      body.style.maxHeight = 'none';
      h = Math.ceil(body.offsetHeight);
      body.style.maxHeight = was;
      mt = getComputedStyle(body).marginTop;
    }
    if (card) card.classList.toggle('open', nowOpen);
    el.setAttribute('aria-expanded', nowOpen ? 'true' : 'false');
    revealAnim(body, nowOpen, h, mt);
    /* ★ 0D.3：设置页收起态要把页脚灰字摆到「关于」块与基准线的中点、并把页脚留白收掉
       （展开态再交回正常流）。这个类切换不会触发 #view 的 MutationObserver，
       所以要自己叫一次；高度在 REVEAL_MS(300ms) 里是连续变的，动画跑完再补一次。 */
    if (window.__syncBarFit){
      window.__syncBarFit();
      setTimeout(window.__syncBarFit, REVEAL_MS + 60);
    }
    return;
  }

