handlers.exportBtn:
if (e.target.closest('#exportBtn')){
    /* 带上完整快照（含标签库/外观设置），否则换台电脑恢复会丢标签 —— 见 snapshot() 的说明 */
    const payload = Object.assign(snapshot(), { exportedAt: new Date().toISOString() });
    const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = '鱼事备份-' + ymd(new Date()) + '.json';
    a.click(); URL.revokeObjectURL(a.href);
    S.lastBackup = Date.now(); save(); refresh();
    toast('已导出备份');
  }

handlers.change.aiFields:
view.addEventListener('change', e => {
  const id = e.target.id;
  if (id === 'aiKeyInput'){
    const had = !!aiKey();
    aiSetKey(e.target.value);
    e.target.value = '';                         // 不回显明文；掩码由重渲染后的 label 显示
    toast(aiKey() ? 'key 存好了（只在设置页显示后四位）' : (had ? 'key 已清空' : '还没填 key'));
    refresh();
    return;
  }
  if (id === 'aiBaseInput'){
    const v = String(e.target.value || '').trim();
    S.aiBase = v || 'https://api.deepseek.com';
    save(); refresh(); toast('接口地址已更新');
    return;
  }
  if (id === 'aiModelInput'){
    const v = String(e.target.value || '').trim();
    S.aiModel = v || 'deepseek-flash';
    save(); refresh(); toast('模型名已更新');
    return;
  }
  /* ★ 7B：「对 AI 的规范设置」——存的是自然语言，原样留着（只限长），空串合法（= 不写规则）。 */
  if (id === 'zoneRulesInput'){
    S.zoneRules = String(e.target.value || '').slice(0, 1000);
    save();
    toast(S.zoneRules.trim() ? '规则存好了 · 以后 AI 按它分区' : '规则清空了 · 改用学到的词 + 模型自己判');
    return;
  }
}

fn.save:
function save(){
  try {
    localStorage.setItem(LS, JSON.stringify({
      items: S.items, lastBackup: S.lastBackup, tags: S.tags,
      statLayout: S.statLayout, hintOpen: S.hintOpen, showHelp: S.showHelp,
      foldedZones: S.foldedZones, theme: S.theme, listMode: S.listMode, voice: S.voice,
      voiceSystem: S.voiceSystem,
      /* ★ v5.0 想法系统的全局状态 */
      ideaUsedAt: S.ideaUsedAt, lastOpenedSeed: S.lastOpenedSeed,
      lastScanAt: S.lastScanAt, ideaReview: S.ideaReview, ideaReviewDone: S.ideaReviewDone,
      captureZone: S.captureZone, ideaGestureSeen: S.ideaGestureSeen, ideaLayout: S.ideaLayout,
      /* ★ v5.0 第 3 批（AI）：只有"设置"，**没有 key**（key 在 AI_KEY_LS 上单独存）。
         ★ 2A：配额字段拆掉，换成常用词表 + 上次焦点。 */
      aiMode: S.aiMode, aiBase: S.aiBase, aiModel: S.aiModel,
      hotwords: S.hotwords, hotwordSeen: S.hotwordSeen, aiAnchor: S.aiAnchor,
      /* ★ 7B：分区表 / 规范设置 / 行为学习的学习记录 —— 一个都不能少（红线 7）。 */
      zones: S.zones, zoneRules: S.zoneRules, zoneHints: S.zoneHints, zoneRev: S.zoneRev,
      setOpen: S.setOpen,
      /* ★ v5.1.2：日期显示口径 + 震动档位 */
      dateShow: S.dateShow, haptic: S.haptic,
      voiceVersion: 2,   /* 语音默认值只迁移一次，之后用户自己的开关说了算（见 load 的说明） */
      /* ★ 阶段1 提醒：总开关进存档 —— 换设备 / 重装后行为一致 */
      notify: !!S.notify,
      /* ★ 0B.2：勾完最后一个子任务是否自动完成父任务（默认关） */
      autoDoneParent: !!S.autoDoneParent
    }));
    saveFailed = false;
  } catch (e){
    if (!saveFailed){
      saveFailed = true;
      toast('保存失败：浏览器写不进去了（空间可能已满，或处于隐私模式），先用「备份」留个底');
    }
  }
}

fn.snapshot:
function snapshot(){
  return {
    items: S.items, tags: S.tags, statLayout: S.statLayout,
    hintOpen: S.hintOpen, showHelp: S.showHelp, lastBackup: S.lastBackup,
    foldedZones: S.foldedZones, theme: S.theme, listMode: S.listMode, voice: S.voice,
    /* ★ v5.0：想法系统的全局状态也进备份，否则换设备后回顾的频次判定会从头开始 */
    ideaUsedAt: S.ideaUsedAt, lastOpenedSeed: S.lastOpenedSeed,
    lastScanAt: S.lastScanAt, ideaReview: S.ideaReview, ideaReviewDone: S.ideaReviewDone,
    captureZone: S.captureZone, ideaGestureSeen: S.ideaGestureSeen, ideaLayout: S.ideaLayout,
    /* ★ v5.0 第 3 批（AI）：**刻意不写 key** —— 设计稿 §14 I-50 的验收：
       备份导出的 JSON 里不含 API key 字段。key 存在 AI_KEY_LS，永不进快照。
       ★ 2A：常用词表与上次焦点也进备份 —— 换设备后不用重新攒词。 */
    aiMode: S.aiMode, aiBase: S.aiBase, aiModel: S.aiModel,
    hotwords: S.hotwords, hotwordSeen: S.hotwordSeen, aiAnchor: S.aiAnchor,
    /* ★ 7B：分区表 / 规范设置 / 行为学习 —— 备份必须带它们（红线 7：
       换设备恢复后，用户自定义的栏目、写的规则、教过的词都得跟着过来）。 */
    zones: S.zones, zoneRules: S.zoneRules, zoneHints: S.zoneHints, zoneRev: S.zoneRev,
    setOpen: S.setOpen,
    /* ★ v5.1.2：日期显示口径 + 震动档位也进备份 —— 换手机/换电脑后不用再调一遍 */
    dateShow: S.dateShow, haptic: S.haptic,
    /* ★ 阶段1 提醒：总开关也进备份 —— 换设备恢复后不用再调一遍 */
    notify: !!S.notify,
    /* ★ 0B.2：这个开关也进备份 —— 换设备后行为保持一致 */
    autoDoneParent: !!S.autoDoneParent
  };
}

fn.load:
function load(){
  try {
    let raw = localStorage.getItem(LS);
    if (!raw){
      const old = localStorage.getItem(LS_OLD);
      if (old){ raw = old; localStorage.setItem(LS, old); }
    }
    if (raw){
      const o = JSON.parse(raw);
      /* 形状校验（代码审查补）：localStorage 是外部可写的，可能被写坏 ——
         半截写入、手工编辑、将来改 schema 都会。原来写成 `o.items || []`，
         一个 items 是对象/字符串的存档会让 renderZoneBody 的 `S.items.map` 抛
         TypeError，清单页整块不渲染；更糟的是本函数末尾的 save() 会把坏形状
         原样写回去，刷新也自愈不了。
         注意**别一刀切成空数组**：那会把还能救的数据一起丢掉。
         所以只筛掉真正不是对象的条目（null / 数字 / 字符串），对象一律保留；
         顺手给缺 id 的补一个（id 是内部键，缺了整棵树都建不起来）。
         拖拽导入那条路径（window drop）当年也只判了"是不是数组"、同样没逐条筛，
         所以两条路都不完整，0A.6 起统一走 sanitizeItems()，不再各写一套。 */
      /* ★ 7B：分区表的建立与**条目归属的迁移**分两步，缺一不可，顺序也不能反：
           ① 先把分区表建好（老存档里可能压根没有 zones 字段）；
           ② 再逐条认 zone —— long / short / repeat 按 ZONE_LEGACY 翻成 k，认不出的落 ''。
         ⚠️ 为什么不能先 sanitizeItems：它会把"分区表里认不出"的 zone 清成 ''，
            而老数据的 long / short / repeat 正是"还没迁、所以认不出"的值 ——
            先洗再迁 = 老条目全掉进未分组（实测踩过）。
         ⚠️ S.items 的赋值**必须在这一步之后**：migrateZones 只动传进去的那份数组
            （load 里是存档对象 o.items）。早先写过"先 sanitizeItems(o.items) 再迁移"，
            结果迁移把 o.items 改了、S.items 还是空的。 */
      S.zones = sanitizeZones(o.zones);
      migrateZones(o);
      S.items = sanitizeItems(o.items);
      S.zoneRev = 1;
      S.zoneRules = (typeof o.zoneRules === 'string') ? o.zoneRules.slice(0, 1000) : '';
      S.zoneHints = sanitizeZoneHints(o.zoneHints);
      zonePruneFolded();
      /* ★ 0A.1：存档里的 parent 可能指向一条已经不存在的条目（删条目只删自己、
         不级联删子条目；手工改存档、恢复备份也会留下悬空引用）——
         统一在装载时收口：悬空的置 null（子条目上浮为根），成环的断开。 */
      sanitizeParents();
      S.lastBackup = o.lastBackup || null;
      /* 标签库：老数据只有 customTags（内置 3 个是写死的），迁成一份完整的 S.tags。
         注意要区分「没有 tags 字段」（老数据 → 迁默认值）和「tags 是空数组」
         （用户把标签全删了 → 就得保持空的，不能把默认的三个又塞回来）。 */
      const hasTags = Array.isArray(o.tags);
      const src = hasTags ? o.tags : TAGS_DEFAULT.concat(Array.isArray(o.customTags) ? o.customTags : []);
      S.tags = normTagList(src);
      S.statLayout = o.statLayout === 'tile' ? 'tile' : 'card';
      S.hintOpen = !!o.hintOpen;
      /* 页面说明文字默认开。老数据里没有这个字段 → 保持默认开；
         显式存过 false 才关（不能写成 `!!o.showHelp`，否则老数据会被静默关掉）。 */
      S.showHelp = o.showHelp !== false;
      /* 折叠起来的清单分区。★ 7B：白名单从写死的 ZONES 改成"当前分区表里真的有这个 k"
         （收口在 zonePruneFolded 里，它是唯一一处）——别把数据里的任意字符串塞进 class 名。
         老数据没有这个字段就是全展开。 */
      S.foldedZones = Array.isArray(o.foldedZones) ? o.foldedZones.filter(k => typeof k === 'string') : [];
      /* 主题三档与清单展示模式：老数据没有这两个字段就保持默认（auto / zone）。
         老备份里单独存过的 LS+'.theme' 在启动块里兜底读取，这里以备份内字段为准。 */
      if (o.theme === 'light' || o.theme === 'dark' || o.theme === 'auto') S.theme = o.theme;
      S.listMode = o.listMode === 'timeline' ? 'timeline' : 'zone';
      /* ★ v3.2 真 bug 修复（用户实测："更新到 3.1 后长按不进语音、没气泡、也不弹权限"）：
         v2.4 及更早把「语音输入」默认写成 false，并随存档持久化（save() 里写了 voice 字段）。
         老用户升级上来读到的永远是那个 false，所以新默认"开启"根本落不了地 ——
         长按只会静默走键盘降级路径，既不弹权限也没有识别气泡。
         修法：加一个**一次性迁移标记** voiceVersion。没有标记的旧存档一律升级为"开启"；
         标记写好之后再关掉，用户的显式选择就会被尊重（不会再被强行打开）。
         注：这里只在"离线识别可用"前不弹任何权限框 —— 权限仍然是**长按那一刻**才申请。 */
      S.voice = (o.voiceVersion === 2) ? !!o.voice : true;
      S.voiceSystem = !!o.voiceSystem;   // v3.4：备用路线（默认关，只在用户勾选后生效）
      /* ★ v5.0 想法系统的全局状态。老存档没有这几个字段 → 保持上面的默认值
         （ideaReview 默认开；ideaUsedAt 为 null 会让回顾抽屉走"超过 7 天"那一档，
          也就是首次打开默认展开一次 —— 这是想要的：新功能得先让你看见）。 */
      S.ideaUsedAt = typeof o.ideaUsedAt === 'string' ? o.ideaUsedAt : null;
      S.lastOpenedSeed = typeof o.lastOpenedSeed === 'string' ? o.lastOpenedSeed : null;
      S.lastScanAt = Number.isFinite(o.lastScanAt) ? o.lastScanAt : 0;
      S.ideaReview = o.ideaReview !== false;
      S.ideaReviewDone = typeof o.ideaReviewDone === 'string' ? o.ideaReviewDone : null;
      /* ★ 7B：可选值现在是 auto / idea / 任意分区的 k（老存档里的 'long' 认不出 → auto）。 */
      S.captureZone = (o.captureZone === 'idea' || o.captureZone === 'auto' || validZoneKey(o.captureZone))
        ? o.captureZone : 'auto';
      S.ideaGestureSeen = o.ideaGestureSeen === true;
      S.ideaLayout = o.ideaLayout === 'tree' ? 'tree' : 'list';
      /* ★ v5.0 第 3 批（AI）：老存档没有这几个字段 → 保持默认（**off**）。
         读坏了（存成不认识的值）也一律退回 'off' —— 隐私开关的失败方向必须是"不联网"，
         宁可不发，也不能因为一个脏数据把内容送出去。 */
      S.aiMode = (o.aiMode === 'title' || o.aiMode === 'full') ? o.aiMode : 'off';
      S.aiBase = (typeof o.aiBase === 'string' && o.aiBase.trim())
        ? o.aiBase.trim() : 'https://api.deepseek.com';
      S.aiModel = (typeof o.aiModel === 'string' && o.aiModel.trim())
        ? o.aiModel.trim() : 'deepseek-flash';
      /* ★ 2A：常用词表与"上次焦点"。
         词表建在这里、进 save()/snapshot()/恢复备份（任务卡：数据结构本卡先建好，
         设置页界面留到 2B）。读进来时按上限截断 + 逐条过滤：
         热词规格是"单词 ≤ 10 汉字"（腾讯云口径），超长的丢掉而不是截断 ——
         截断后的词会与用户说的词不同音，等于往纠错里灌噪声。 */
      S.hotwords = sanitizeHotwords(o.hotwords);
      S.hotwordSeen = sanitizeHotwordSeen(o.hotwordSeen);
      S.aiAnchor = (typeof o.aiAnchor === 'string' && o.aiAnchor.trim())
        ? o.aiAnchor.trim().slice(0, 60) : null;
      /* ★ v5.0 设置页折叠：老存档没有这个字段 → 全收起（默认）；只收字符串，别的丢掉 */
      S.setOpen = Array.isArray(o.setOpen)
        ? o.setOpen.filter(k => typeof k === 'string' && k).slice(0, 12) : [];
      /* ★ v5.1.2：日期显示口径与震动档位。
         日期：老存档没有 → 三段全开（就是现在的行为）；显式存过 false 才算关
         —— 写成 `ds.y !== false` 而不是 `!!ds.y`，否则"用户把三段全关掉"这个状态
         会在下次启动被静默改回全开（跟 showHelp 那条同一个坑）。 */
      const ds = (o.dateShow && typeof o.dateShow === 'object') ? o.dateShow : null;
      S.dateShow = {
        y: ds ? ds.y !== false : true,
        m: ds ? ds.m !== false : true,
        d: ds ? ds.d !== false : true,
      };
      /* 震动：读坏了退回 'std'（宁可正常震，也别因为一个脏值变成"完全不震"让人以为坏了） */
      S.haptic = ['off', 'low', 'std', 'high'].includes(o.haptic) ? o.haptic : 'std';
      /* ★ 0B.2：新开关。老存档没有这个字段 → 保持默认关（不能写成 !!o.autoDoneParent 之外的花样，
         也别因为缺字段就打开 —— 这是"自动替你动数据"的开关，默认必须是关） */
      S.autoDoneParent = o.autoDoneParent === true;
      /* ★ 阶段1 提醒：总开关。老存档没有这个字段 → 默认**开**。
         写成 `o.notify !== false` 而不是 `!!o.notify` —— 后者会让"用户显式关掉提醒"
         在下次启动被静默打开（与 showHelp / dateShow 同一个坑）。 */
      S.notify = o.notify !== false;
    }
  } catch (e){}
  syncTags();
  save();      // 把迁移后的规范结构写回去（老数据只有 customTags，不写回就一直是旧形状）
}

fn.refreshNotifyPerm:
function refreshNotifyPerm(){
  const box = document.getElementById('notifyPerm');
  if (!box) return;
  box.hidden = !(notifyBridge() && S.notify && notifyPerm() === 'denied');
}

fn.refreshNotifyExact:
function refreshNotifyExact(){
  const box = document.getElementById('notifyExact');
  const full = document.getElementById('notifyFull');
  const on = !!(notifyBridge() && S.notify);
  if (box){
    const bad = on && notifyExact() !== 'granted';
    box.hidden = !bad;
    if (bad){
      const txt = document.getElementById('notifyExactTxt');
      if (txt) txt.textContent = '提醒可能会晚几分钟：系统没给精确闹钟权限';
    }
  }
  /* ★ 5A：全屏响铃那一行整体只在有桥时露（网页版 / 老壳没有这两个方法）。
     开关状态从原生读；「系统没给全屏权限」这句只在**开关真打开**时才说 ——
     关着的时候默认路径根本不碰全屏 Intent，提示它只会让人以为哪里坏了。 */
  const b = notifyBridge();
  const hasAlarmFull = !!(b && typeof b.getAlarmFull === 'function');
  const row = document.getElementById('alarmFullRow');
  const sw = document.getElementById('alarmFullSw');
  const af = hasAlarmFull && notifyAlarmFull();
  if (row) row.hidden = !hasAlarmFull;
  if (sw) sw.setAttribute('aria-checked', af ? 'true' : 'false');
  if (full){
    const bad = on && af && notifyFullScreen() !== 'granted';
    full.hidden = !bad;
    if (bad){
      const txt = document.getElementById('notifyFullTxt');
      if (txt) txt.textContent = '锁屏上不会全屏弹，改成横幅 + 响铃提醒';
    }
  }
  /* ★ 5C：上次提醒的对账。它回答的是"响了但晚了，怪谁"——
     排的时刻是**我们算的**、实际时刻是**系统交的**，两个数一摆，责任立刻分明。
     晚了 ≥60 秒才多给一枚「去放行」（跳电池优化页），平时不打扰。 */
  const lastEl = document.getElementById('notifyLast');
  if (lastEl){
    const lf = on ? notifyLastFire() : null;
    lastEl.hidden = !lf;
    if (lf){
      const late = Math.round((lf.fired - lf.sched) / 1000);
      const tail = late >= 60 ? '（晚了 ' + late + ' 秒）'
        : (late <= -60 ? '（早了 ' + (-late) + ' 秒）' : '（准点）');
      lastEl.innerHTML = '<span>上次提醒：排 ' + esc(notifyLastLabel(lf.sched))
        + ' · 实际 ' + esc(notifyLastLabel(lf.fired)) + esc(tail) + '</span>';
      if (late >= 60){
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'pill';
        btn.setAttribute('data-act', 'batteryopen');
        btn.textContent = '去放行';
        lastEl.appendChild(btn);
      }
    }
  }
}

fn.setFoldInit:
function setFoldInit(){
  const cards = view.querySelectorAll('.set-card');
  cards.forEach((card, i) => {
    const h3 = card.querySelector(':scope > h3');
    if (!h3) return;
    const key = h3.textContent.trim() || ('c' + i);
    const id = 'setb-' + i;
    const open = S.setOpen.indexOf(key) >= 0;
    /* 顺序要紧：先把 h3 之后的所有节点搬进 body，再动 h3 —— 反了会把 body 自己也搬进去 */
    const body = document.createElement('div');
    body.className = 'set-body';
    body.id = id;
    while (h3.nextSibling) body.appendChild(h3.nextSibling);
    const head = document.createElement('button');
    head.type = 'button';
    head.className = 'set-head';
    head.dataset.act = 'setfold';
    head.dataset.key = key;
    head.setAttribute('aria-expanded', open ? 'true' : 'false');
    head.setAttribute('aria-controls', id);
    const chev = document.createElement('span');
    chev.className = 'sh-chev';
    chev.setAttribute('aria-hidden', 'true');
    chev.textContent = '▸';
    card.insertBefore(head, h3);
    head.appendChild(h3);
    head.appendChild(chev);          // 箭头靠右由 .sh-chev 的 margin-left:auto 负责
    card.appendChild(body);
    card.classList.toggle('open', open);
  });
}
